UPDATE acc_subject SET code = #{code}, name = #{name}, category = #{category}, direction = #{direction},
       note = #{note, jdbcType=VARCHAR}, active = #{active}
 WHERE id = #{id}

UPDATE acc_bank_account SET bank_name = #{bankName}, account_no = #{accountNo}, holder = #{holder, jdbcType=VARCHAR},
       purpose = #{purpose, jdbcType=VARCHAR}, note = #{note, jdbcType=VARCHAR}, active = #{active}
 WHERE id = #{id}

UPDATE acc_card SET issuer = #{issuer}, last4 = #{last4}, nickname = #{nickname, jdbcType=VARCHAR}, holder = #{holder, jdbcType=VARCHAR},
       bank_account_id = #{bankAccountId, jdbcType=BIGINT}, note = #{note, jdbcType=VARCHAR}, active = #{active}
 WHERE id = #{id}
